fn mapping_target_for<'a>(map: &SyntaxMapping<'a>, path: &str) -> Option<MappingTarget<'a>> {
    let candidate = Candidate::new(path);
    let candidate_filename = std::path::Path::new(path).file_name().map(Candidate::new);
    for entry in map.mappings().iter().rev() {
        let entry = MappingEntry::from_tuple(entry);
        if entry.glob_matcher().is_match_candidate(&candidate)
            || candidate_filename
                .as_ref()
                .map_or(false, |filename| entry.glob_matcher().is_match_candidate(filename))
        {
            return Some(*entry.target());
        }
    }
    None
}

#[test]
fn basic() {
    let mut map = SyntaxMapping::empty();
    map.insert("/path/to/Cargo.lock", MappingTarget::MapTo("TOML"))
        .ok();
    map.insert("/path/to/.ignore", MappingTarget::MapTo("Git Ignore"))
        .ok();

    assert_eq!(
        mapping_target_for(&map, "/path/to/Cargo.lock"),
        Some(MappingTarget::MapTo("TOML"))
    );
    assert_eq!(mapping_target_for(&map, "/path/to/other.lock"), None);

    assert_eq!(
        mapping_target_for(&map, "/path/to/.ignore"),
        Some(MappingTarget::MapTo("Git Ignore"))
    );
}

#[test]
fn user_can_override_builtin_mappings() {
    let mut map = SyntaxMapping::builtin();

    assert_eq!(
        mapping_target_for(&map, "/etc/profile"),
        Some(MappingTarget::MapTo("Bourne Again Shell (bash)"))
    );
    map.insert("/etc/profile", MappingTarget::MapTo("My Syntax"))
        .ok();
    assert_eq!(
        mapping_target_for(&map, "/etc/profile"),
        Some(MappingTarget::MapTo("My Syntax"))
    );
}

#[test]
fn builtin_mappings() {
    let map = SyntaxMapping::builtin();

    assert_eq!(
